INSERT INTO landing_content(id,schema_version,revision,payload) VALUES (1,1,1,'{"schemaVersion": 1, "revision": 1, "title": "Ласточка — детская оздоровительная гимнастика в Белгороде", "description": "Занятия для детей 5–14 лет: движение, координация и здоровые привычки. Мини-группы и индивидуальные занятия с Паргевом Арутюняном.", "phone": "+7 906 602-30-21", "telegram": "Pargev31", "blocks": [{"id": "hero", "kind": "hero", "title": "Двигаться легко. Расти уверенно.", "text": "Оздоровительная гимнастика для осанки, сильной спины и радости движения. В маленькой группе, с большим вниманием к каждому.", "image": "hero.webp", "alt": "Иллюстрация занятия детей с тренером в светлом зале", "items": ["Белгород", "Дети 5–14 лет"], "motionPreset": "hero-reveal", "visible": true}, {"id": "approach", "kind": "approach", "title": "Маленькие шаги. Большая уверенность.", "text": "Помогаем подружиться с движением. Без гонки за результатом — с заботой, игрой и вниманием к своему телу.", "items": ["В своём темпе|Замечаем возможности ребёнка и подбираем посильные упражнения.", "Через интерес|Баланс, координация и игра делают каждое занятие открытием.", "С поддержкой|Тренер рядом: объясняет, помогает и замечает маленькие победы."], "motionPreset": "approach-story", "visible": true}, {"id": "formats", "kind": "formats", "title": "Свой формат для каждого.", "text": "Выбираем комфортный ритм и уделяем внимание каждому ребёнку.", "items": ["Мини-группа|Движение, игра и новые друзья. Небольшие группы и внимание тренера.", "Индивидуально|Персональный темп, упражнения и поддержка один на один.", "Первое занятие|Знакомство с тренером и пространством. Условия уточните у студии."], "motionPreset": "formats-reveal", "visible": true}, {"id": "first-visit", "kind": "steps", "title": "Начнём со знакомства.", "text": "Первое занятие — без лишнего волнения.", "items": ["Выберите занятие|Посмотрите свободное время в расписании.", "Оставьте заявку|Создайте аккаунт родителя и добавьте ребёнка.", "Дождитесь подтверждения|Администратор подтвердит запись. Возьмите удобную форму и воду."], "motionPreset": "none", "visible": true}, {"id": "coach", "kind": "coach", "title": "Паргев Арутюнян", "text": "Основатель и тренер студии «Ласточка». Внимание к ребёнку, уважение к его темпу и радость движения — основа нашего подхода.", "image": "coach.webp", "alt": "Иллюстрация тренера; изображение из дизайн-концепции", "motionPreset": "none", "visible": true}, {"id": "faq", "kind": "faq", "title": "Родители спрашивают.", "text": "Всё, что хочется знать до первого шага.", "items": ["С какого возраста можно заниматься?|Программа студии рассчитана на детей 5–14 лет. Подходящий формат поможет выбрать тренер.", "Что взять с собой?|Удобную спортивную одежду и воду. Остальные детали уточните у тренера перед посещением.", "Это медицинские занятия?|Нет. Это физкультурно-оздоровительные занятия, без диагностики и лечения.", "Можно записать двоих детей?|Да. Добавьте карточки детей в кабинете и отправьте отдельную заявку для каждого.", "Когда запись считается подтверждённой?|После одобрения администратором. Статус заявки виден в кабинете.", "Где находится студия и сколько стоит занятие?|Студия в Белгороде. Точный адрес, действующие цены и условия первого посещения уточните у тренера."], "motionPreset": "none", "visible": true}, {"id": "contacts", "kind": "contacts", "title": "Пусть движение станет радостью.", "text": "Белгород. Точный адрес, стоимость и подходящий формат подскажем при знакомстве.", "items": [], "motionPreset": "none", "visible": true}]}'::jsonb) ON CONFLICT (id) DO NOTHING;
